def first_bad_version(is_bad: list[bool]) -> int:
    lo, hi = 0, len(is_bad) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if is_bad[mid]:
            hi = mid          # first bad is mid or earlier
        else:
            lo = mid + 1      # first bad is after mid
    return lo
